-- Agent skills — the "/" menu's catalogue.
--
-- Sourced from CaseMark's open medical-skills library
-- (github.com/CaseMark/skills, skills/med), filtered to what a behavioral-health
-- practice actually does and mapped onto the agent that owns the work:
-- Friday holds clinical documentation, assessment, care planning and
-- medication; Sal holds coding and revenue cycle; Bev holds credentialing and
-- compliance.
--
-- Rows, not a TypeScript array, because this list grows: adding a skill should
-- be an INSERT, not a deploy. `prompt` is what the composer inserts today —
-- when skills get real dispatch it becomes the instruction the route loads.
--
-- Lives in the PUBLIC/reference database. Nothing here is PHI: these are
-- procedure definitions, not patient data.

CREATE TABLE IF NOT EXISTS agent_skills (
  slug        TEXT PRIMARY KEY,
  agent_id    TEXT NOT NULL,
  group_label TEXT NOT NULL,
  title       TEXT NOT NULL,
  description TEXT NOT NULL,
  prompt      TEXT NOT NULL,
  source      TEXT NOT NULL DEFAULT 'casemark/skills',
  active      BOOLEAN NOT NULL DEFAULT true,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_skills_agent ON agent_skills(agent_id) WHERE active;

COMMENT ON TABLE agent_skills IS 'Catalogue behind the composer''s "/" menu. One row per skill; agent_id scopes which agent offers it.';

