ON CONFLICT (slug) DO UPDATE
  SET agent_id = EXCLUDED.agent_id,
      group_label = EXCLUDED.group_label,
      title = EXCLUDED.title,
      description = EXCLUDED.description,
      prompt = EXCLUDED.prompt;
